        assert canonicalize_action("take lamp 1 from desk 1") == ("take", "lamp 1", "desk 1")

    def test_put_in(self):
        assert canonicalize_action("put lamp 1 in desk 1") == ("put", "lamp 1", "desk 1")

    def test_put_on(self):
